public static Map<IField, String> fieldNames(Set<IField> fields) { 
	final Map<String, List<IField>> name2Field = new LinkedHashMap<String, List<IField>>();
	final Map<IField,String> field2Name = new LinkedHashMap<IField, String>();

	for(IField field : fields) {
		String fieldName = field.getName().toString();
		List<IField> namedFields = name2Field.get(fieldName);
		if (namedFields == null) {
			namedFields = new ArrayList<IField>(3);
			name2Field.put(fieldName, namedFields);
		}
		namedFields.add(field);
	}

	for(Map.Entry<String, List<IField>> entry : name2Field.entrySet()) {
		List<IField> fieldsList = entry.getValue();
		if (fieldsList.size() == 1) {
			field2Name.put(fieldsList.get(0), entry.getKey());
		} else {
			for(IField field : fieldsList) {
				field2Name.put(field, field.getName().toString());
			}
		}
	}

	return field2Name;
}

